/* V2.3 incremental workflow workbench; original inventory UI remains intact. */
'use strict';
const Flow={masters:null,names:{REGISTERED:'待检验',PASSED:'合格',FAILED:'不合格',CANCELLED:'已取消',DRAFT:'草稿',LOADED:'装车完成',DEPARTED:'已离场',REVERSED:'已冲销',RECORDED:'已登记',VOID:'已作废'},can:p=>Business.can(p),async data(){return this.masters=await Business.load();},open:(t,h)=>Business.open(t,h),field(label,name,type='text',value='',extra=''){return `<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;},select(label,name,rows,key='name',value){return `<label>${esc(label)}<select name="${name}">${Business.options(rows,value,key)}</select></label>`;},numbers(){return `<label>捆包编号（每行一捆，最多500捆）<textarea name="bundle_ids" required rows="5">${esc([...selected].join('\n'))}</textarea></label>`;},parse(form){const b=Object.fromEntries(new FormData(form));if(b.bundle_ids)b.bundle_ids=b.bundle_ids.split(/[\s,，]+/).filter(Boolean);return b;},form(title,html,save){this.open(title,`<form id="flow-form" class="user-form">${html}<p id="flow-error" class="error" role="alert"></p><button class="button primary">保存</button></form>`);$('flow-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{await save(this.parse(e.target));notify('操作成功，记录已保存');}catch(err){$('flow-error').textContent=err.message;e.submitter.disabled=false;}};},async action(url,version,body={}){return API.request(url,{method:'POST',body:{version,...body}});},
 async samples(){const r=await API.request('/samples');this.open('取样批次与检验',`<button id="sample-new" class="button primary" ${this.can('sample:write')?'':'disabled'}>新建取样批次</button><p>一个批次可关联多捆，同一捆可复检。取样不会扣减实物库存。</p>${this.table(r.items,['code','sample_date','agency','status'],'sample')}`);$('sample-new').onclick=()=>this.sampleForm().catch(e=>notify(e.message));this.bindDetails('sample',id=>this.sample(id));},
 table(rows,keys,kind){const labels={code:'单号',sample_date:'日期',agency:'取样机构',status:'状态',vehicle_no:'车辆',customer_name:'客户',contract_display:'合同号',total_weight:'装车净重（吨）',net_weight:'净重（吨）',difference:'差异（吨）',kind:'类型',created_at:'创建时间',reversal_status:'冲销状态'};return `<div class="business-table"><table><thead><tr>${keys.map(k=>`<th>${labels[k]||k}</th>`).join('')}<th>操作</th></tr></thead><tbody>${rows.map(r=>`<tr>${keys.map(k=>`<td>${esc(this.names[r[k]]||r[k]||'—')}</td>`).join('')}<td><button class="detail-button" data-flow="${kind}" data-id="${r.id}">详情</button></td></tr>`).join('')}</tbody></table></div>`;},bindDetails(kind,fn){document.querySelectorAll(`[data-flow="${kind}"]`).forEach(b=>b.onclick=()=>fn(b.dataset.id).catch(e=>notify(e.message)));},
 async sampleForm(){const d=await this.data();this.form('新建取样单 / 批次',this.select('项目','project_id',d.projects)+this.select('客户','customer_id',d.customers.filter(x=>x.active))+this.field('取样日期','sample_date','date',new Date().toISOString().slice(0,10),'required')+this.field('取样机构','agency','text','','required maxlength="160"')+this.numbers(),async b=>{const s=await API.request('/samples',{method:'POST',body:b});await this.sample(s.id);});},
 async sample(id){const s=await API.request('/samples/'+id);this.open('取样批次 · '+s.code,`<p>${esc(s.sample_date)} · ${esc(s.agency)} · ${esc(this.names[s.status])}</p><p>检验结果 / 取消原因：${esc(s.result||'尚未登记')}</p><p>${s.items.map(x=>esc(x.bundle_no)).join('、')}</p>${s.status==='REGISTERED'&&this.can('sample:write')?'<label>检验结果 / 取消原因<textarea id="sample-result" maxlength="4000"></textarea></label><div class="business-toolbar"><button class="button primary" data-sample-action="PASSED">登记合格</button><button class="button secondary" data-sample-action="FAILED">登记不合格</button><button class="button secondary" data-sample-action="cancel">取消取样</button></div>':''}<p id="sample-error" class="error"></p><div id="flow-attachments"></div>`);document.querySelectorAll('[data-sample-action]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await this.action('/samples/'+id+'/'+b.dataset.sampleAction,s.version,{result:$('sample-result').value});await this.sample(id);await render();}catch(e){$('sample-error').textContent=e.message;b.disabled=false;}});await this.attachments('samples',id,'sample:write');},
 async attachments(route,id,permission){const a=await API.request('/'+route+'/'+id+'/attachments');$('flow-attachments').innerHTML='<h3>报告 / 磅单附件</h3>'+a.items.map(x=>`<p><button class="text-button" data-attachment="${x.id}">${esc(x.filename)}</button><small> SHA256 ${esc(x.sha256)}</small></p>`).join('')+(this.can(permission)?'<label>上传 PDF / PNG / JPEG（最多256KiB）<input id="flow-file" type="file" accept=".pdf,.png,.jpg,.jpeg"></label><button id="upload-flow-file" class="button secondary">保存附件</button><p id="attachment-error" class="error"></p>':'');document.querySelectorAll('[data-attachment]').forEach(b=>b.onclick=async()=>{try{const result=await API.request('/'+route+'/'+id+'/attachments/'+b.dataset.attachment,{binary:true});const link=document.createElement('a'),url=URL.createObjectURL(result.blob);link.href=url;link.download=a.items.find(x=>x.id===b.dataset.attachment).filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){notify(e.message);}});if($('upload-flow-file'))$('upload-flow-file').onclick=async e=>{e.target.disabled=true;try{const file=$('flow-file').files[0];if(!file||file.size>262144)throw Error('请选择不超过256KiB的附件');const bytes=new Uint8Array(await file.arrayBuffer());let raw='';for(const b of bytes)raw+=String.fromCharCode(b);await API.request('/'+route+'/'+id+'/attachments',{method:'POST',body:{filename:file.name,base64:btoa(raw)}});await this.attachments(route,id,permission);}catch(err){$('attachment-error').textContent=err.message;e.target.disabled=false;}};}
};
const baseBusinessMenu=Business.menu.bind(Business);Business.menu=function(){baseBusinessMenu();const area=document.querySelector('.business-menu');for(const [label,permission,method] of [['取样检验','sample:read','samples'],['捆包 / 车辆检斤','weigh:read','weighings'],['车辆装车','load:read','loads'],['出库审批与离场','outbound:read','outbounds'],['货位移库','inventory:read','moves']]){const b=document.createElement('button');b.className='button secondary';b.textContent=label;b.disabled=!Flow.can(permission);b.onclick=()=>Flow[method]().catch(e=>notify(e.message));area.append(b);}};

Object.assign(Flow,{
 async weighings(){const r=await API.request('/weighings');this.open('捆包与车辆检斤',`<button id="weigh-new" class="button primary" ${this.can('weigh:write')?'':'disabled'}>新建检斤记录</button><p>净重 = 毛重 − 皮重。差异只提示，不改原捆包重量；车辆关联装车单后用于出库审批。</p>${this.table(r.items,['code','kind','vehicle_no','net_weight','difference','status'],'weigh')}`);$('weigh-new').onclick=()=>this.weighForm().catch(e=>notify(e.message));this.bindDetails('weigh',id=>this.weigh(id));},
 async weighForm(load){const d=await this.data();this.form('登记检斤',this.select('项目','project_id',d.projects,'name',load?.project_id)+this.select('客户','customer_id',d.customers.filter(x=>x.active),'name',load?.customer_id)+`<label>类型<select name="kind"><option value="VEHICLE">车辆</option><option value="BUNDLE">单捆</option></select></label>`+this.field('车牌','vehicle_no','text',load?.vehicle_no||'')+`<input name="loading_id" type="hidden" value="${esc(load?.id||'')}"><p>关联装车单：${esc(load?.code||'独立检斤；正式出库请从装车详情登记本车检斤。')}</p>`+this.field('毛重（吨）','gross_weight','text','','required inputmode="decimal"')+this.field('皮重（吨，单捆可填0）','tare_weight','text','0','required inputmode="decimal"')+this.field('平台秤编号','scale_no','text','','required')+this.field('检斤时间（含时区ISO）','weighed_at','text',new Date().toISOString(),'required')+(load?`<label>捆包编号<textarea name="bundle_ids" readonly>${load.items.map(x=>esc(x.bundle_no)).join('\n')}</textarea></label>`:this.numbers()),async b=>{if(load){b.project_id=load.project_id;b.customer_id=load.customer_id;}const r=await API.request('/weighings',{method:'POST',body:b});await this.weigh(r.id);});},
 async weigh(id){const r=await API.request('/weighings/'+id);this.open('检斤记录 · '+r.code,`<p>车牌 ${esc(r.vehicle_no||'单捆')} · 平台秤 ${esc(r.scale_no)} · ${esc(r.weighed_at)}</p><dl><dt>毛重（吨）</dt><dd>${esc(Tonnes.format(r.gross_weight))}</dd><dt>皮重（吨）</dt><dd>${esc(r.tare_weight)}</dd><dt>检斤净重（吨）</dt><dd>${esc(Tonnes.format(r.net_weight))}</dd><dt>捆包合计（吨）</dt><dd>${esc(r.bundle_weight)}</dd><dt>差异（吨）</dt><dd>${esc(r.difference)} ${Number(r.difference)!==0?'⚠ 需异常复核，未修改捆包原重':''}</dd></dl><p>状态 ${esc(this.names[r.status])} · 作废原因 ${esc(r.void_reason||'—')}</p><p>${r.items.map(x=>esc(x.bundle_no)).join('、')}</p>${r.status==='RECORDED'&&this.can('weigh:write')?'<label>作废原因<input id="weigh-void-reason"></label><button id="weigh-void" class="button secondary">作废（保留原磅单）</button>':''}<div id="flow-attachments"></div>`);if($('weigh-void'))$('weigh-void').onclick=async()=>{try{await this.action('/weighings/'+id+'/void',r.version,{reason:$('weigh-void-reason').value});await this.weigh(id);}catch(e){notify(e.message);}};await this.attachments('weighings',id,'weigh:write');}
});

Object.assign(Flow,{
 async loads(){const r=await API.request('/loads');this.open('车辆装车管理',`<button id="load-new" class="button primary" ${this.can('load:write')?'':'disabled'}>新建车辆装车单</button><p>只接受客户已锁定库存。装车完成及车辆未正式离场前均不扣减实物库存。</p>${this.table(r.items,['code','vehicle_no','status'],'load')}`);$('load-new').onclick=()=>this.loadForm().catch(e=>notify(e.message));this.bindDetails('load',id=>this.load(id));},
 async loadForm(){const d=await this.data();this.form('新建车辆装车单',this.select('项目','project_id',d.projects)+this.select('客户（对应有效锁定）','customer_id',d.customers.filter(x=>x.active))+this.field('车牌','vehicle_no','text','','required')+this.field('运输商','carrier','text','','required')+this.field('装车点','loading_point','text','','required')+this.field('装车时间（含时区ISO）','loaded_at','text',new Date().toISOString(),'required')+this.numbers()+'<p>可先在库存查询按分配客户、已预留筛选，跨页勾选后进入本表。此处编号会在服务器和数据库再次检查。</p>',async b=>{const d=await API.request('/loads',{method:'POST',body:b});await this.load(d.id);});},
 async load(id){const d=await API.request('/loads/'+id);this.open('装车单 · '+d.code,`<a class="button secondary" href="/stock-map?project_id=${d.project_id}&amp;load_id=${d.id}&amp;loading_id=${d.id}">地图查看本车库存</a><p>客户 ${esc(d.customer_name)} · 合同 ${esc(d.contract_nos.join('、')||'历史未关联')} ${esc(d.contract_notice)}<br>车牌 ${esc(d.vehicle_no)} · 运输商 ${esc(d.carrier)} · 装车点 ${esc(d.loading_point)}<br>时间 ${esc(d.loaded_at)} · 状态 ${esc(this.names[d.status])}</p><p>合计 ${esc(Tonnes.format(d.total_weight))} 吨（数据库精确合计）</p><p>${d.items.map(x=>`${esc(x.bundle_no)}：${esc(Tonnes.format(x.net_weight))} 吨`).join('<br>')}</p><p>取消/退装原因：${esc(d.cancel_reason||'—')}</p><div class="business-toolbar">${d.status==='DRAFT'&&this.can('load:write')?'<button class="button primary" data-load-action="complete">装车完成</button>':''}${['DRAFT','LOADED'].includes(d.status)&&this.can('load:write')?'<button class="button secondary" data-load-action="cancel">取消装车</button><button class="button secondary" data-load-action="unload">整车退装</button>':''}${d.status==='LOADED'?'<button id="packing-list" class="button secondary">下载装箱单 Excel</button>':''}${d.status==='LOADED'&&this.can('weigh:write')?'<button id="load-weigh" class="button secondary">登记本车检斤</button>':''}</div><label>取消/退装原因<input id="load-reason" maxlength="500"></label><p id="load-error" class="error"></p><div id="outbound-entry"></div>`);document.querySelectorAll('[data-load-action]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await this.action('/loads/'+id+'/'+b.dataset.loadAction,d.version,{reason:$('load-reason').value});await this.load(id);}catch(e){$('load-error').textContent=e.message;b.disabled=false;}});if($('packing-list'))$('packing-list').onclick=async()=>{try{const r=await API.request('/loads/'+id+'/packing-list',{binary:true}),u=URL.createObjectURL(r.blob),a=document.createElement('a');a.href=u;a.download='装箱单.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}catch(e){notify(e.message);}};if($('load-weigh'))$('load-weigh').onclick=()=>this.weighForm(d).catch(e=>notify(e.message));if(this.outboundEntry)await this.outboundEntry(d);}
});

Object.assign(Flow.names,{VEHICLE:'车辆检斤',BUNDLE:'捆包检斤',CREATED:'待生产确认',PACKING_CONFIRMED:'待商务复核',COMMERCIAL_APPROVED:'待安保实际离场核验',GATE_VERIFIED:'待生产确认扣库',NONE:'无冲销',REQUESTED:'待冲销批准',AUTHORIZED:'待核验实物退回',RETURN_VERIFIED:'待生产确认冲销',CONFIRMED:'已确认'});
Object.assign(Flow,{
 async outboundEntry(load){if(load.status!=='LOADED'||!this.can('load:write'))return;const [tickets,orders]=await Promise.all([API.request('/weighings'),API.request('/outbounds')]),existing=orders.items.find(x=>x.loading_id===load.id&&x.status!=='CANCELLED');if(existing){$('outbound-entry').innerHTML='<button id="existing-outbound" class="button primary">查看本车出库审批</button>';$('existing-outbound').onclick=()=>this.outbound(existing.id).catch(e=>notify(e.message));return;}const valid=tickets.items.filter(x=>x.loading_id===load.id&&x.status==='RECORDED');$('outbound-entry').innerHTML=valid.length?`<h3>发起出库审批</h3><label>本车检斤单<select id="outbound-ticket">${valid.map(x=>`<option value="${x.id}">${esc(x.code)} · 差异 ${esc(x.difference)} 吨</option>`).join('')}</select></label><button id="outbound-create" class="button primary">创建出库审批单</button>`:'<p>请先登记本车检斤，再创建出库审批单。</p>';if($('outbound-create'))$('outbound-create').onclick=async()=>{try{const d=await API.request('/outbounds',{method:'POST',body:{loading_id:load.id,weighing_id:$('outbound-ticket').value}});await this.outbound(d.id);}catch(e){notify(e.message);}};},
 async outbounds(){const r=await API.request('/outbounds');for(const x of r.items)x.contract_display=x.contract_nos.join('、')+(x.contract_notice?' · '+x.contract_notice:'');this.open('出库审批与实际离场',`<div class="business-toolbar"><a class="button primary" href="/outbounds/loads">车辆装车管理</a><a class="button secondary" href="/outbounds/loads/new">新建装车单</a><a class="button secondary" href="/outbounds/weighings">检斤记录</a></div><a class="button secondary" href="/stock-map?outbound=DRAFT_LOADING">待装车地图</a> <a class="button secondary" href="/stock-map?outbound=LOADED">已装车待离场地图</a><p>装车详情发起出库。生产确认装箱单 → 商务复核 → 安保核验实际离场 → 生产确认扣库。不同职责必须独立操作。</p>${this.table(r.items,['code','vehicle_no','customer_name','contract_display','total_weight','status','reversal_status'],'outbound')}`);this.bindDetails('outbound',id=>this.outbound(id));},
 async outbound(id){const d=await API.request('/outbounds/'+id),actions=[];const add=(action,label,permission)=>{if(this.can(permission))actions.push([action,label]);};if(['CREATED','PACKING_CONFIRMED'].includes(d.status)&&Number(d.weighing.difference)!==0&&!d.variance_by)add('variance-approve','主管接受重量差异','outbound:supervise');if(d.status==='CREATED')add('packing','生产确认装箱单','outbound:packing');if(d.status==='PACKING_CONFIRMED')add('commerce','商务复核通过','outbound:commerce');if(d.status==='COMMERCIAL_APPROVED')add('gate','安保核验实际离场','outbound:gate');if(d.status==='GATE_VERIFIED')add('depart','生产确认实际离场并扣减库存','outbound:depart');if(['CREATED','PACKING_CONFIRMED','COMMERCIAL_APPROVED'].includes(d.status)){add('cancel','主管取消出库审批','outbound:supervise');const p={CREATED:'outbound:packing',PACKING_CONFIRMED:'outbound:commerce',COMMERCIAL_APPROVED:'outbound:gate'}[d.status];add('reject','本节点驳回',''+p);}if(d.status==='DEPARTED'){if(d.reversal_status==='NONE')add('reverse-request','申请出库冲销（须实物退回）','outbound:supervise');if(d.reversal_status==='REQUESTED')add('reverse-approve','独立主管批准冲销','outbound:supervise');if(d.reversal_status==='AUTHORIZED')add('return-verify','安保核验货物实际退回','outbound:gate');if(d.reversal_status==='RETURN_VERIFIED')add('reverse-confirm','生产确认退回并冲销库存','outbound:depart');}
 this.open('出库单 · '+d.code,`<a class="button secondary" href="/stock-map?project_id=${d.project_id}&amp;load_id=${d.loading_id}&amp;loading_id=${d.loading_id}">地图查看车辆占用</a><p>客户 ${esc(d.customer_name)} · 合同 ${esc(d.contract_nos.join('、')||'历史未关联')} ${esc(d.contract_notice)}<br>车辆 ${esc(d.load.vehicle_no)} · 状态 ${esc(this.names[d.status])}<br>冲销状态 ${esc(this.names[d.reversal_status])}<br>检斤净重 ${esc(d.weighing.net_weight)} 吨 · 捆包净重 ${esc(d.weighing.bundle_weight)} 吨 · 差异 ${esc(d.weighing.difference)} 吨<br>离场时间 ${esc(d.departed_at||'尚未确认')} · 冲销原因 ${esc(d.reversal_reason||'—')}</p><p>${d.items.map(x=>esc(x.bundle_no)).join('、')}</p><h3>节点记录</h3><ol>${d.steps.map(x=>`<li>${esc(x.occurred_at)} · ${esc(x.actor_name)} · ${esc(this.actions[x.action]||x.action)} · ${esc(x.result==='REJECTED'?'驳回':'通过')} · ${esc(x.remark)}</li>`).join('')}</ol>${actions.length?'<label>审批/核验备注（必填）<textarea id="outbound-remark" maxlength="1000"></textarea></label>'+this.attestations(actions)+'<div class="business-toolbar">'+actions.map(([a,l])=>`<button class="button secondary" data-outbound-action="${a}">${l}</button>`).join('')+'</div>':''}<p id="outbound-error" class="error" role="alert"></p>`);
 document.querySelectorAll('[data-outbound-action]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const body={remark:$('outbound-remark').value,packing_checked:($('packing-checked')?.checked||false),documents_checked:($('documents-checked')?.checked||false),conditions_checked:($('conditions-checked')?.checked||false),vehicle_checked:($('vehicle-checked')?.checked||false),actual_departure:($('actual-departure')?.checked||false),actual_return:($('actual-return')?.checked||false)};if(['gate','return-verify'].includes(b.dataset.outboundAction))body.observed_at=$('outbound-observed').value;await this.action('/outbounds/'+id+'/'+b.dataset.outboundAction,d.version,body);await this.outbound(id);await render();notify('审批/库存操作已记录');}catch(e){$('outbound-error').textContent=e.message;b.disabled=false;}});}
});

Object.assign(Flow,{
 async moves(){const r=await API.request('/moves');this.open('货位调整与移库',`<button id="move-new" class="button primary" ${this.can('move:write')?'':'disabled'}>登记移库</button><p>整批原子调整位置，不改变实物净重。已进入装车的捆包须先取消或退装。</p>${this.table(r.items,['code','status','created_at'],'move')}`);$('move-new').onclick=()=>this.moveForm().catch(e=>notify(e.message));this.bindDetails('move',id=>this.move(id));},
 async moveForm(){const d=await this.data();this.form('确认货位调整',this.select('项目','project_id',d.projects)+this.select('客户（货权或有效锁定客户）','customer_id',d.customers.filter(x=>x.active))+this.select('目标货位','target_location_id',d.locations.filter(x=>x.active),'code')+this.field('移库原因','reason','text','','required maxlength="500"')+this.numbers(),async b=>{const d=await API.request('/moves',{method:'POST',body:b});await this.move(d.id);await render();});},
 async move(id){const d=await API.request('/moves/'+id);this.open('移库单 · '+d.code,`<p>状态 ${esc(this.names[d.status])} · 原因 ${esc(d.reason)} · 确认时间 ${esc(d.confirmed_at)}</p><p>实物库存重量不变。</p>${d.items.map(x=>{const p=d.positions.find(p=>p.bundle_id===x.id);return `<p>${esc(x.bundle_no)} · ${esc(p?.from_location)} → ${esc(p?.to_location)} · ${esc(Tonnes.format(x.net_weight))} 吨</p>`;}).join('')}`);}
});

for(const [name,method] of [['出库管理','outbounds'],['取样管理','samples']]){const button=document.querySelector(`[data-info="${name}"]`);if(button){button.removeAttribute('data-info');button.querySelector('small')?.remove();button.onclick=()=>Flow[method]().catch(e=>notify(e.message));}}

Flow.actions={'variance-approve':'重量差异主管审批',packing:'生产确认装箱单',commerce:'商务复核',gate:'安保核验实际离场',depart:'生产确认离场扣库',reject:'节点驳回',cancel:'取消出库审批','reverse-request':'申请冲销','reverse-approve':'独立主管批准冲销','return-verify':'安保核验实物退回','reverse-confirm':'生产确认退回冲销'};
Flow.attestations=function(actions){const kinds=actions.map(x=>x[0]);let h=kinds.some(x=>['gate','return-verify'].includes(x))?'<label>现场观察时间（含时区ISO）<input id="outbound-observed" value="'+esc(new Date().toISOString())+'"></label>':'';for(const [id,label,needed] of [['packing-checked','已核对装箱单',['packing']],['documents-checked','已复核出库资料',['commerce']],['conditions-checked','已复核离场条件',['commerce']],['vehicle-checked','已核对实际车辆',['gate']],['actual-departure','已核验车辆实际离场（不是计划离场）',['gate','depart']],['actual-return','已核验整车货物实际退回厂内',['return-verify','reverse-confirm']]])if(needed.some(x=>kinds.includes(x)))h+='<label><input id="'+id+'" type="checkbox"> '+label+'</label>';return h;};
